	assert.True(t, strings.HasPrefix(result.EtcdSnapshotPath, "/backups/etcd-snapshot-"))
	assert.True(t, strings.HasSuffix(result.EtcdSnapshotPath, ".db"))
	assert.Equal(t, etcd.backupPath, result.EtcdSnapshotPath)
